// Run executes dupfind with caller-supplied streams.
func Run(args []string, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("dupfind", flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	summary := fs.Bool("summary", false, "write summary CSV")
	minSize := fs.Int64("min-size", 1, "minimum file size in bytes")
	if err := fs.Parse(args); err != nil {
		fmt.Fprintln(stderr, "usage: dupfind [--summary] [--min-size bytes] <directory>")
		return 2
	}
	if *minSize <= 0 || fs.NArg() != 1 {
		fmt.Fprintln(stderr, "usage: dupfind [--summary] [--min-size bytes] <directory>")
		return 2
	}
	root := fs.Arg(0)
	info, err := os.Stat(root)
	if err != nil || !info.IsDir() {
		fmt.Fprintf(stderr, "error: %s is not an accessible directory\n", root)
		return 1
	}
	groups, err := discovery.Find(root, *minSize, stderr)
	if err != nil {
		fmt.Fprintf(stderr, "error: cannot scan directory: %v\n", err)
		return 1
	}
	if *summary {
		if err := output.WriteSummary(stdout, groups); err != nil {
			fmt.Fprintf(stderr, "error: cannot write output: %v\n", err)
			return 1
		}
		return 0
	}
	if err := output.WriteListing(stdout, groups); err != nil {
		fmt.Fprintf(stderr, "error: cannot write output: %v\n", err)
		return 1
	}
	return 0
}
package discovery

import (
	"crypto/sha256"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
)

// File is a regular file relative to the scan root.
type File struct {
	Path string
	Size int64
}

// Group contains files with identical size and SHA-256 digest.
type Group struct {
	Size   int64
	Digest string
	Paths  []string
}

// Find walks root and groups duplicate regular files. Read failures are warnings.
func Find(root string, minSize int64, warning io.Writer) ([]Group, error) {
	bySize := make(map[int64][]string)
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.Type()&os.ModeSymlink != 0 || !entry.Type().IsRegular() {
			return nil
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		if info.Size() == 0 || info.Size() < minSize {
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		bySize[info.Size()] = append(bySize[info.Size()], filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		return nil, err
	}
	groups := make([]Group, 0)
	for size, paths := range bySize {
		if len(paths) < 2 {
			continue
		}
		byDigest := make(map[string][]string)
		for _, rel := range paths {
			full := filepath.Join(root, filepath.FromSlash(rel))
			f, err := os.Open(full)
			if err != nil {
				fmt.Fprintf(warning, "warning: cannot read %s: %v\n", rel, err)
				continue
			}
			h := sha256.New()
			_, readErr := io.Copy(h, f)
			closeErr := f.Close()
			if readErr != nil {
				fmt.Fprintf(warning, "warning: cannot read %s: %v\n", rel, readErr)
				continue
			}
			if closeErr != nil {
				fmt.Fprintf(warning, "warning: cannot read %s: %v\n", rel, closeErr)
				continue
			}
			byDigest[fmt.Sprintf("%x", h.Sum(nil))] = append(byDigest[fmt.Sprintf("%x", h.Sum(nil))], rel)
		}
		for digest, members := range byDigest {
			if len(members) < 2 {
				continue
			}
			sort.Slice(members, func(i, j int) bool { return members[i] < members[j] })
			groups = append(groups, Group{Size: size, Digest: digest, Paths: members})
		}
	}
	return groups, nil
}
package output

import (
	"encoding/csv"
	"fmt"
	"io"
	"sort"

	"dupfind/internal/discovery"
)

func WriteListing(w io.Writer, groups []discovery.Group) error {
	ordered := append([]discovery.Group(nil), groups...)
	sort.Slice(ordered, func(i, j int) bool {
		a, b := ordered[i], ordered[j]
		ra, rb := a.Size*int64(len(a.Paths)-1), b.Size*int64(len(b.Paths)-1)
		if ra != rb {
			return ra > rb
		}
		return a.Digest < b.Digest
	})
	cw := csv.NewWriter(w)
	if err := cw.Write([]string{"group", "size", "sha256", "path"}); err != nil {
		return err
	}
	for i, g := range ordered {
		for _, p := range g.Paths {
			if err := cw.Write([]string{fmt.Sprint(i + 1), fmt.Sprint(g.Size), g.Digest, p}); err != nil {
				return err
			}
		}
	}
	cw.Flush()
	return cw.Error()
}

func WriteSummary(w io.Writer, groups []discovery.Group) error {
	var files, bytes int64
	for _, g := range groups {
		n := int64(len(g.Paths) - 1)
		files += n
		bytes += g.Size * n
	}
	cw := csv.NewWriter(w)
	if err := cw.Write([]string{"groups", "duplicate_files", "reclaimable_bytes"}); err != nil {
		return err
	}
	if err := cw.Write([]string{fmt.Sprint(len(groups)), fmt.Sprint(files), fmt.Sprint(bytes)}); err != nil {
		return err
	}
	cw.Flush()
	return cw.Error()
}
