 ('listing-empty',[],'empty'),
 ('listing-relative-paths',[],'nested'),
 ('listing-csv-path',[],'comma'),
]
for name,args,kind in cases:
    with tempfile.TemporaryDirectory() as temp:
        root=Path(temp)
        if kind == 'empty':
            target=root/'empty'; target.mkdir(); (target/'one').write_bytes(b''); (target/'two').write_bytes(b'')
        elif kind == 'filtered':
            target=root
            for name_, data in [('small-a',b'x'),('small-b',b'x'),('large-a',b'large payload'),('large-b',b'large payload')]: (root/name_).write_bytes(data)
        elif kind == 'nested':
            target=root/'scan'; a=target/'a'; b=target/'b'; a.mkdir(parents=True); b.mkdir()
            (a/'copy.bin').write_bytes(b'shared bytes'); (b/'copy.bin').write_bytes(b'shared bytes')
        else:
            target=root; (root/'a,copy').write_bytes(b'same'); (root/'b').write_bytes(b'same')
        try:
            result=subprocess.run(['./cmd/dupfind',*args,str(target)],capture_output=True)
            print(name, 'started', result.returncode)
        except Exception as exc:
            print(name, type(exc).__name__, str(exc))
